mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY bp.SEQTRAVELPOST DESC) AS rnum, bp.SEQTRAVELPOST AS seqTravelPost, bp.SEQMEMBER AS seqMember, bp.TITLE AS title, bp.CONTENT AS content, bp.VIEWCOUNT AS viewCount, bp.STATUS AS status, TO_CHAR(bp.CREATEDATE, 'YYYY-MM-DD') AS createDate, TO_CHAR(bp.UPDATEDATE, 'YYYY-MM-DD') AS updateDate, m.NAME AS writerName, f.SAVEDNAME AS savedName FROM TRAVEL_POST bp INNER JOIN MEMBER m ON bp.SEQMEMBER = m.SEQMEMBER LEFT JOIN ( SELECT SEQTRAVELPOST, SAVEDNAME, ROW_NUMBER() OVER ( PARTITION BY SEQTRAVELPOST ORDER BY SEQTRAVELPOSTFILE ASC ) AS file_rnum FROM TRAVEL_POST_FILE ) f ON bp.SEQTRAVELPOST = f.SEQTRAVELPOST AND f.file_rnum = 1 WHERE bp.STATUS = 'NORMAL'
AND ( bp.TITLE LIKE '%' || #{searchWord} || '%' OR REGEXP_REPLACE(bp.CONTENT, '<[^>]+>', '') LIKE '%' || #{searchWord} || '%' )
) WHERE rnum BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE TRAVEL_POST
SET VIEWCOUNT = VIEWCOUNT + 1
WHERE SEQTRAVELPOST = #{seqTravelPost}

mapper.select:
SELECT SEQMEMBER
FROM TRAVEL_POST
WHERE SEQTRAVELPOST = #{seqTravelPost}
